"""Real workshop media and a catalogue that separates parts from finishes."""
from pathlib import Path
import re,shutil,json
from PIL import Image
import build_iteration3 as b

def build():
 sources={
  'amg-air-test.mp4':Path(r'D:\Dynabook doc\Alpha Tech Solutions\Proyectos\AMG 35\canard\Canard v5\WhatsApp Video 2026-11-11 at 20.56.32.mp4'),
  'civic-scan-pov.mp4':b.BASE/'Honda civic Type R/scan pov.mp4',
  'porsche-wheel-render.jpeg':b.BASE/'porsche 924 board/Volante fibra.jpeg'}
 for name,source in sources.items():shutil.copy2(source,b.ASSETS/name)
 # Posters extracted from the supplied videos; original media is kept intact.
 for key in ['amg','civic']:
  target=b.ASSETS/f'{key}-video-poster.webp'
  frame=b.ROOT.parent/'video-review'/f'{key}-0.5.png'
  if frame.exists():Image.open(frame).save(target,quality=90)
  assert target.exists(),f'Missing video poster: {target}'
 for file,en in [('index.html',False),('en.html',True)]:
  t=lambda es,eng:eng if en else es
  p=b.SITE/file;s=p.read_text(encoding='utf-8')
  def quote(kind,reference,label):return f'<a href="#contact" class="button quote-project" data-service="{kind}" data-reference="{reference}">{label} ↗</a>'
  def video(key,label):
   source='amg-air-test.mp4' if key=='amg' else 'civic-scan-pov.mp4'
   return f'<video class="workshop-video" controls playsinline preload="none" poster="assets/{key}-video-poster.webp" aria-label="{label}"><source src="assets/{source}" type="video/mp4"><a href="assets/{source}">{t("Abrir video","Open video")}</a></video>'
  amg=f'''<section id="amg-development" class="section engineering-story"><div class="section-heading"><div><p class="eyebrow">AMG A35 / CANARDS V5</p><h2>{t('Del diseño al vehículo.','From design to the vehicle.')}</h2></div><p>{t('Desarrollo aerodinámico específico para el Mercedes-AMG A35: diseño, cálculo y observación del comportamiento del flujo sobre el prototipo instalado.','A dedicated aerodynamic development for the Mercedes-AMG A35: design, calculation and observation of airflow over the installed prototype.')}</p></div><div class="workshop-layout"><div><figure class="front-geometry"><img src="assets/amg-canards-solid.webp" alt="{t('Canard v5 con referencia del frontal del AMG A35','V5 canard with AMG A35 front reference')}" loading="lazy"><figcaption>{t('Geometría v5 con referencia del frontal','V5 geometry with front reference')}</figcaption></figure><button class="button" data-open-model="amg-canards">{t('Explorar conjunto en 3D','Explore assembly in 3D')}</button><div class="story-facts"><div><strong>{t('DESARROLLO PROPIO','OUR OWN DEVELOPMENT')}</strong><p>{t('Diseño y cálculo orientados al A35','Design and calculation tailored to the A35')}</p></div><div><strong>{t('AVANCE EN TALLER','WORKSHOP PROGRESS')}</strong><p>{t('Prototipo instalado · prueba visual de flujo','Installed prototype · visual airflow test')}</p></div></div>{quote('aero','AMG A35 · Canards v5',t('Cotizar desarrollo aerodinámico','Quote aerodynamic development'))}</div><div>{video('amg',t('Prueba de aire con los canards instalados en el Mercedes-AMG A35','Airflow test with canards installed on the Mercedes-AMG A35'))}<p class="video-caption">{t('Prueba de aire con humo · 14 s. Observación cualitativa; no es una medición de carga aerodinámica.','Smoke airflow test · 14 s. Qualitative observation; not a downforce measurement.')}</p></div></div></section>'''
  s=re.sub(r'<section id="amg-development".*?</section>',lambda _:amg,s,flags=re.S)
  # Keep the model/photo separation explicit on project cards.
  def project(m):
   text=m.group(0)
   if 'data-open-model="porsche-wheel"' in text:
    text=text.replace('assets/porsche-wheel-solid.webp','assets/porsche-wheel-render.jpeg')
    text=re.sub(r'<span class="badge">.*?</span>',f'<span class="badge">{t("RENDER DE DISEÑO · EN DESARROLLO","DESIGN RENDER · IN DEVELOPMENT")}</span>',text,count=1)
    text=text.replace('</article>',f'<p class="fine">{t("Imagen renderizada de la propuesta. El visor muestra el escaneo de referencia.","Rendered design proposal. The viewer shows the reference scan.")}</p></article>')
   if 'data-open-model="amg-canards"' in text:
    text=text.replace('</article>',f'<a class="textlink progress-link" href="#amg-development">{t("Ver prueba de aire en el vehículo","Watch the on-vehicle airflow test")} →</a></article>')
   return text
  s=re.sub(r'<article class="project">.*?</article>',project,s,flags=re.S)
  s=re.sub(r'<section id="civic-scan".*?</section>','',s,flags=re.S)
  civic=f'''<section id="civic-scan" class="section civic-scan"><div class="workshop-layout scan-pov-layout"><div><p class="eyebrow">HONDA CIVIC TYPE R / SCAN POV</p><h2>{t('El escaneo, desde dentro.','Inside the scanning process.')}</h2><p>{t('Así capturamos la zona inferior del parachoques trasero del Civic Type R: una referencia geométrica para estudiar el encaje y desarrollar nuevas piezas.','Capturing the lower rear-bumper area of the Civic Type R: a geometric reference for studying fit and developing new parts.')}</p><p class="fine">{t('Registro del proceso de escaneo. Es un trabajo distinto del skinning de los cubreespejos.','Scanning process footage. This is separate from the mirror-cover skinning project.')}</p>{quote('scan','Honda Civic Type R · Escaneo de parachoques',t('Cotizar un escaneo para mi proyecto','Quote a scan for my project'))}</div><div>{video('civic',t('Escaneo POV de la zona inferior del parachoques trasero del Honda Civic Type R','POV scan of the lower rear bumper of the Honda Civic Type R'))}<p class="video-caption">{t('Video del proceso · 3 min · reproducción manual.','Process video · 3 min · manual playback.')}</p></div></div></section>'''
